"""Complete rbtree.c and node/root representation, with each fixup case."""
def register(topic, q, detail):
    def lesson(title, path, symbol, why, principle, use, reading, qa, cards):
        topic(title, '라이브러리·알고리즘', path, symbol,
              why, principle, use, reading, *(q(*x) for x in qa),
              details=[detail(*x) for x in cards])

    lesson('레드블랙 노드·부모 주소와 색을 한 정수에 담기', 'include/linux/rbtree_types.h', 'rb_node',
        '균형 이진 탐색 트리의 연결 정보와 색을 어떤 필드로 표현하는지 배웁니다.',
        'rb_node는 __rb_parent_color, rb_right, rb_left를 가집니다. 정렬된 주소의 낮은 비트를 색 정보에 사용하고 나머지로 부모 주소를 표현합니다. rb_root는 루트 포인터 한 개이며 rb_root_cached는 여기에 가장 왼쪽 노드 포인터를 추가합니다. 오른쪽 끝은 공간 대비 사용 이득을 고려해 기본 캐시에 넣지 않습니다.',
        '자료 객체 안에 rb_node 멤버를 넣고 rb_entry로 원래 객체에 접근합니다. RB_ROOT와 RB_ROOT_CACHED로 빈 루트를 초기화합니다. 부모·색 정수를 일반 데이터 주소로 직접 역참조하지 말고 접근 매크로를 사용합니다.',
        '노드 정렬 속성, 두 루트 형식과 초기화 매크로를 읽으세요.',
        [('cached 루트가 기본으로 추가 저장하는 것은?', '가장 왼쪽 노드다', '모든 노드의 정렬된 배열이다', 'rb_leftmost를 추가해 최소 원소 접근을 O(1)로 만듭니다. 전체 노드를 별도 배열에 복사하는 구조가 아닙니다.'),
         ('부모·색 정수를 그대로 포인터로 쓰면 왜 문제가 생기는가?', '낮은 색 비트가 주소에 섞여 있기 때문이다', '부모 포인터는 항상 문자열이기 때문이다', '일반 부모 접근은 낮은 비트를 마스크로 제거합니다. 일부 내부 빨간 노드 helper만 색 0이라는 조건으로 직접 변환합니다.')],
        [('다섯 불변조건', '노드는 빨강 또는 검정, 루트와 NULL 잎은 검정, 빨강 노드의 자식은 검정, 모든 루트→잎 경로의 검정 수는 같습니다. 같은 검정 높이와 연속 빨강 금지로 최장 경로가 검정 높이의 두 배를 넘지 않아 O(log n) 높이를 유지합니다.'),
         ('수명 책임', '노드와 자료 객체의 할당·해제는 트리 API가 대신 수행하지 않습니다. 연결된 노드가 살아 있는 동안 키와 필드의 계약을 호출자가 유지합니다.')])

    lesson('레드블랙 회전·새 루트에 부모와 색 넘기기', 'lib/rbtree.c', '__rb_rotate_set_parents',
        '부분 트리 회전이 자식 연결뿐 아니라 부모와 색도 함께 바꾸는 이유를 배웁니다.',
        'old가 있던 자리의 부모와 색 정보를 new로 복사합니다. old의 부모를 new로 바꾸고 지정 색을 설정합니다. 마지막으로 이전 부모의 자식 포인터 또는 전체 루트 포인터를 new로 교체합니다. 회전의 좌우 자식 연결은 호출 위치에서 먼저 준비하고 이 helper가 상위 연결을 완성합니다.',
        '회전은 키의 중위 순서를 유지해야 합니다. 상위 연결만 바꾸고 자식의 부모를 놓치면 다음·이전 순회가 깨집니다. 실제 균형 코드는 WRITE_ONCE로 자식 필드를 쓰며 회전별 확장 콜백도 호출합니다.',
        'rb_parent, rb_set_parent_color, __rb_change_child의 역할을 연결하세요.',
        [('old가 전체 루트라면 회전의 상위 연결은 어디를 바꾸는가?', 'root->rb_node를 new로 바꾼다', '없는 부모의 왼쪽 필드를 역참조한다', '부모가 NULL일 때 __rb_change_child는 전체 루트 포인터를 갱신합니다. 일반 부모 자식 갱신과 다른 경계입니다.'),
         ('회전에서 중위 키 순서는 어떻게 되어야 하는가?', '회전 전후에 동일해야 한다', '모든 키의 대소 관계를 뒤집어야 한다', '회전은 트리의 모양과 높이를 바꾸지만 검색 순서를 보존합니다. 색 변경과 연결 갱신은 이 조건을 유지하며 균형을 복구합니다.')],
        [('빨간 부모 helper', 'RB_RED는 0이므로 rb_red_parent는 빨간 노드의 부모·색 값을 바로 부모 주소로 바꿉니다. 임의의 검정 노드에 같은 해석을 적용하지 않습니다.'),
         ('검정으로 바꾸기', 'rb_set_black은 내부 빨간 노드에 RB_BLACK을 더합니다. 이미 검정인 임의 노드를 반복 호출해도 되는 범용 색 설정으로 읽지 않습니다.')])

    lesson('레드블랙 삽입·루트와 빨간 삼촌의 색 변경', 'lib/rbtree.c', '__rb_insert',
        '새 빨간 노드가 만드는 위반을 색 변경으로 위쪽에 전달하는 과정을 배웁니다.',
        '새 노드는 빨간 상태로 시작합니다. 부모가 없으면 검정 루트로 만들고, 부모가 검정이면 바로 끝납니다. 부모와 삼촌이 모두 빨강이면 둘을 검정으로 바꾸고 조부모를 빨강으로 바꿉니다. 현재 노드를 조부모로 올려 반복하므로 위쪽에 생길 수 있는 연속 빨강 위반을 처리합니다. 좌우 부모 위치에 대해 같은 절차가 대칭으로 있습니다.',
        '먼저 비교 기준으로 삽입 위치를 찾아 rb_link_node로 연결한 뒤 색 복구를 호출합니다. 색 복구 함수가 키를 비교해 삽입 위치를 찾는다고 생각하지 않습니다. 초기 루트와 연속 색 변경 사례를 직접 추적합니다.',
        'parent==NULL, 검정 부모, Case 1의 continue를 읽으세요.',
        [('부모와 삼촌을 검정으로 바꾸고 조부모를 빨강으로 바꾸면?', '위반이 위쪽으로 이동할 수 있어 반복을 계속한다', '전체 트리의 모든 색을 무조건 검정으로 바꾼다', '해당 아래 경로의 검정 높이는 유지하지만 조부모와 그 부모가 연속 빨강일 수 있습니다. 현재 위치를 조부모로 올려 확인합니다.'),
         ('새 노드의 부모가 검정이면 색 복구는?', '추가 회전 없이 끝날 수 있다', '반드시 두 번 회전한다', '빨간 새 노드는 검정 높이를 늘리지 않고 검정 부모와 연속 빨강도 만들지 않습니다. 그 경로에서는 복구가 필요 없습니다.')],
        [('루트 처리', '첫 노드 삽입과 Case 1이 루트까지 올라온 경우 모두 부모 없음 분기로 연결됩니다. 루트는 검정이어야 합니다.'),
         ('입력 조건', '이미 연결된 노드를 다시 삽입하거나 키를 바꾸어 위치를 깨뜨리지 않습니다. 변경 접근의 직렬화와 노드 수명은 호출자 책임입니다.')])

    lesson('레드블랙 삽입·꺾인 경로와 직선 경로 회전', 'lib/rbtree.c', '__rb_insert',
        '검정 삼촌을 가진 삽입 위반을 한 번 또는 두 번 회전으로 해결하는 방법을 배웁니다.',
        '부모가 조부모의 왼쪽이고 새 노드가 부모의 오른쪽이면 꺾인 모양입니다. Case 2는 부모에서 왼쪽 회전해 직선 모양으로 만듭니다. Case 3은 조부모에서 오른쪽 회전하고 새 부분 루트를 이전 조부모의 색으로, 내려간 조부모를 빨강으로 설정합니다. 부모가 오른쪽인 경우 회전 방향을 모두 반대로 적용합니다.',
        '30,10,20 삽입은 꺾인 경로를, 30,20,10은 직선 경로를 관찰하는 작은 예입니다. 자식 이동, 부모 갱신과 augment_rotate 호출을 함께 따라가며 회전 횟수만 보고 내용을 생략하지 않습니다.',
        'Case 2의 parent=node 갱신과 Case 3의 break를 읽으세요.',
        [('30,10,20에서 왼쪽 부모와 오른쪽 새 노드가 만드는 모양은?', '꺾인 경로이므로 먼저 부모 회전이 필요하다', '항상 이미 직선 경로다', '30의 왼쪽 10에서 다시 오른쪽 20으로 이동합니다. 부모 회전으로 직선을 만든 뒤 조부모 회전을 적용합니다.'),
         ('오른쪽 부모와 왼쪽 새 노드의 대칭 Case 2 방향은?', '부모에서 오른쪽 회전이다', '항상 전체 루트를 삭제한다', '왼쪽 부모의 오른쪽 노드 사례는 왼쪽 회전입니다. 좌우 대칭 사례에서는 부모의 오른쪽 회전으로 직선 형태를 만듭니다.')],
        [('옮긴 자식', '회전 사이의 부분 트리 tmp가 있으면 새로운 부모로 갱신합니다. 노드 수와 중위 순서가 유지되어야 합니다.'),
         ('확장 요약값', '각 구조 회전은 old,new를 확장 콜백에 전달합니다. 일반 트리는 빈 콜백을 사용하고 요약 필드가 있는 트리는 회전에 맞게 요약을 갱신합니다.')])

    lesson('레드블랙 삭제 복구·빨간 형제를 검정 형제로 바꾸기', 'lib/rbtree.c', '____rb_erase_color',
        '검정 노드 하나가 부족한 경로를 복구할 때 빨간 형제를 먼저 변환하는 이유를 배웁니다.',
        '삭제 뒤 node 경로의 검정 수가 형제 경로보다 하나 부족합니다. 왼쪽 node의 형제가 빨강이면 부모에서 왼쪽 회전하고 올라간 형제가 부모의 색을, 내려간 부모가 빨강을 갖습니다. 그러면 node의 새 형제는 검정인 이전 형제의 왼쪽 자식입니다. 부족분을 바로 없앤 것이 아니라 이후 Case 2~4를 적용할 형태로 바꾼 것입니다.',
        '원본은 첫 회차 node=NULL로 시작할 수 있습니다. 유효한 레드블랙 삭제에서 형제와 필요한 자식이 존재하는 불변조건을 사용하므로 임의로 손상된 트리에 이 내부 함수를 직접 호출하지 않습니다.',
        'Case 1 뒤 sibling=tmp1이 되는 이유를 읽으세요.',
        [('빨간 형제 회전 뒤 바로 검정 부족분이 사라진다고 보는가?', '아니며 검정 형제 형태로 바꾼 뒤 후속 경우를 처리한다', '항상 모든 삭제 복구가 즉시 끝난다', 'Case 1은 다음 경우를 다룰 수 있게 모양과 색을 바꿉니다. 원본은 새 형제의 자식을 조사하며 계속 실행합니다.'),
         ('node가 오른쪽에 있는 대칭 Case 1의 방향은?', '부모에서 오른쪽 회전이다', '언제나 부모에서 왼쪽 회전이다', '왼쪽 node의 빨간 오른쪽 형제는 왼쪽 회전입니다. 오른쪽 node에서는 왼쪽 형제를 올리는 오른쪽 회전입니다.')],
        [('삭제 불변조건', 'node는 검정 또는 첫 회차 NULL이며 루트가 아닙니다. node를 지나는 경로는 검정 하나가 부족합니다. 이 상태를 유지하면서 부족분을 없애거나 부모로 올립니다.'),
         ('확장 콜백', '색만 바뀌는 경우와 실제 연결이 회전하는 경우를 구분합니다. 연결 회전에서는 요약값을 위한 augment_rotate가 실행됩니다.')])

    lesson('레드블랙 삭제 복구·형제 색 변경과 부족분 올리기', 'lib/rbtree.c', '____rb_erase_color',
        '검정 형제의 두 자식도 검정일 때 회전 없이 부족분을 처리하는 방법을 배웁니다.',
        '형제와 그 두 자식이 검정이면 형제를 빨강으로 바꿉니다. 형제 쪽에서도 검정 하나를 줄여 두 아래 경로를 맞춥니다. 부모가 빨강이면 부모를 검정으로 바꾸어 부족분을 채우고 끝냅니다. 부모가 검정이면 부모를 현재 node로 올려 더 위에서 부족한 검정 하나를 해결합니다. 부모가 루트까지 올라가면 끝납니다.',
        'NULL 자식도 검정으로 취급합니다. 형제만 빨강으로 바꾸고 전체 복구가 항상 끝난다고 해석하지 말고 부모 색과 parent 갱신을 함께 읽습니다. 양쪽 대칭 Case 2가 같은 불변조건을 유지하는지 확인합니다.',
        'rb_is_red(parent), rb_set_black, node=parent와 continue를 읽으세요.',
        [('Case 2에서 부모가 검정이면 다음 동작은?', '부족분을 부모 경로로 올려 반복할 수 있다', '검정 높이를 확인하지 않고 항상 종료한다', '형제 색 변경으로 아래 두 경로는 맞지만 전체가 하나 부족합니다. 검정 부모는 즉시 보충할 빨간 색 여유가 없어 위쪽 복구가 필요합니다.'),
         ('Case 2에서 부모가 빨강이면 왜 검정으로 바꾸는가?', '부족한 검정 하나를 채우기 위해서다', '이진 탐색 키를 더 큰 값으로 바꾸기 위해서다', '아래 양쪽에서 하나 부족한 검정 수를 부모의 빨강→검정 변경으로 보충합니다. 색 복구는 키 자체를 바꾸지 않습니다.')],
        [('루트 경계', '위로 올린 node의 부모가 NULL이면 전체 루트에 도달했습니다. 모든 경로에서 동일하게 검정 수가 줄어든 상황은 같은 높이 조건을 깨뜨리지 않습니다.'),
         ('빨간 형제 이후', '앞 Case 1에서 내려간 부모는 빨강입니다. 이후 Case 2라면 그 부모를 검정으로 바꾸어 끝날 수 있다는 연결을 원본 주석에서 확인합니다.')])

    lesson('레드블랙 삭제 복구·가까운 자식과 먼 자식 회전', 'lib/rbtree.c', '____rb_erase_color',
        '검정 형제의 빨간 자식을 활용해 검정 높이를 회복하는 마지막 두 경우를 배웁니다.',
        '왼쪽 node에서 형제의 먼 오른쪽 자식이 검정이고 가까운 왼쪽 자식이 빨강이면 Case 3으로 형제에서 오른쪽 회전합니다. 이를 통해 빨간 먼 자식이 있는 Case 4 형태를 만듭니다. Case 4는 부모에서 왼쪽 회전하고 새 부분 루트에 부모의 기존 색을 넘기며 내려간 부모와 먼 자식을 검정으로 만듭니다. 오른쪽 node에서는 좌우를 반대로 적용합니다.',
        '가깝다·멀다는 전체 배열 주소가 아니라 부족한 node 쪽과의 위치 관계입니다. Case 3 중간에는 일시적인 연속 빨강이 생길 수 있지만 바로 이어지는 Case 4가 해결합니다. 각 회전에서 부모·자식과 색을 모두 추적합니다.',
        'tmp1·tmp2, Case 3 뒤 sibling 갱신과 Case 4의 break를 읽으세요.',
        [('왼쪽 부족 경로에서 형제의 가까운 자식은?', '형제의 왼쪽 자식이다', '형제의 부모 주소에서 가까운 메모리다', '부족한 node는 형제의 왼쪽 방향에 있으므로 형제의 왼쪽 자식이 가깝고 오른쪽이 멉니다. 메모리 주소 거리와 관계없습니다.'),
         ('Case 3의 목적은?', 'Case 4가 처리할 빨간 먼 자식 형태를 만드는 것이다', '노드를 정렬 기준 없이 무작위로 바꾸는 것이다', '가까운 빨간 자식을 회전으로 올려 먼 자식 조건을 만듭니다. Case 4의 부모 회전과 색 변경이 실제 부족분을 해결합니다.')],
        [('일시 상태', '원본은 Case 3에서 부모가 빨강이면 중간에 연속 빨강이 가능하다고 설명합니다. 다음 Case 4까지 하나의 복구 과정으로 이해해야 합니다.'),
         ('최종 보존', 'Case 4 후 중위 키 순서, 각 자식의 부모, 연속 빨강 금지와 같은 검정 높이가 함께 맞아야 합니다. 정렬 순서만으로 균형 복구 성공을 판단하지 않습니다.')])

    lesson('레드블랙 기본 API·빈 확장 콜백으로 구현 공유', 'lib/rbtree.c', 'rb_erase',
        '일반 트리와 확장 트리가 같은 균형 알고리즘을 공유하는 구조를 배웁니다.',
        'rb_insert_color는 __rb_insert에 dummy_rotate를 전달합니다. rb_erase는 __rb_erase_augmented에 propagate·copy·rotate가 비어 있는 dummy_callbacks를 전달하고, 반환된 rebalance 부모가 있으면 색 복구를 실행합니다. __always_inline 경로는 컴파일러가 빈 콜백 동작을 제거할 수 있도록 구성되었습니다.',
        '일반 자료에는 기본 API를 사용합니다. 삭제는 정확히 연결된 노드 포인터를 필요로 하고 객체를 해제하거나 RB_CLEAR_NODE를 대신 실행하지 않습니다. 제거 후 수명 정리와 빈 표식 설정이 필요한지는 호출자가 처리합니다.',
        '세 dummy 함수와 dummy_callbacks, rebalance 검사와 공개 심볼을 읽으세요.',
        [('rb_erase 호출만으로 객체 메모리가 해제되는가?', '아니며 호출자가 수명을 관리한다', '항상 내부에서 kfree를 실행한다', '트리 연결과 균형을 고치는 API입니다. 원본에는 객체 해제나 할당 함수가 없고 빈 표식 초기화도 별도로 필요합니다.'),
         ('기본 삭제가 확장 helper를 쓰는 이유는?', '빈 콜백을 이용해 같은 연결·균형 구현을 공유하기 위해서다', '모든 기본 노드에 구간 최대값을 강제로 추가하기 위해서다', 'dummy_callbacks는 아무 요약값도 갱신하지 않습니다. 구조 구현을 공유하면서 확장 자료가 없는 경로의 불필요한 동작을 제거할 수 있습니다.')],
        [('삭제 연결 단계', '확장 header helper는 자식 0·1개 또는 후계자 대체를 처리하고 검정 부족분이 남았을 때 부모를 반환합니다. 기본 rb_erase는 그 결과에 따라 색 복구를 선택합니다.'),
         ('공개와 내부', 'EXPORT_SYMBOL과 내부 inline helper의 역할을 구분합니다. 내부 복구 함수를 직접 호출하는 대신 공개 삽입·삭제 API의 조건을 따릅니다.')])

    lesson('레드블랙 확장 진입·회전에 요약 콜백 전달', 'lib/rbtree.c', '__rb_insert_augmented',
        '부분 트리 요약값을 가진 자료에서 실제 회전 코드에 갱신 함수를 연결하는 방법을 배웁니다.',
        '__rb_insert_augmented는 같은 __rb_insert 구현에 사용자 augment_rotate를 전달합니다. 비-inline __rb_erase_color는 동일한 ____rb_erase_color에 사용자 회전 함수를 전달합니다. 기본 API는 빈 함수를, 확장 API는 요약값을 갱신하는 함수를 사용하므로 균형 조건은 같은 코드로 유지됩니다.',
        '삽입 경로의 요약값을 먼저 갱신한 뒤 확장 삽입을 호출해야 합니다. 확장 API가 어떤 필드가 요약인지 자동으로 찾아 전체 트리를 재계산한다고 가정하지 않습니다. 캐시·요약·균형의 각 책임을 연결해서 읽습니다.',
        '두 확장 진입 함수의 인자와 내부 호출을 기본 wrapper와 비교하세요.',
        [('확장 삽입 전에 검색 경로의 요약값을 누가 준비하는가?', '삽입을 수행하는 호출자다', '노드 키와 무관하게 모든 필드를 자동 탐색한다', '확장 삽입은 균형 회전의 콜백을 실행합니다. 회전되지 않는 검색 경로의 요약 갱신은 호출 흐름에서 미리 준비해야 합니다.'),
         ('확장과 기본 API의 색 복구 알고리즘은?', '같은 구현에 다른 회전 콜백을 연결한다', '서로 무관한 정렬 알고리즘이다', '두 경로는 __rb_insert와 ____rb_erase_color를 공유합니다. 요약 갱신을 위한 콜백이 추가되는 점이 다릅니다.')],
        [('균형과 요약', '올바른 색과 검정 높이가 있어도 요약값이 틀리면 가지치기 검색이 필요한 결과를 놓칠 수 있습니다. 두 불변조건을 별도로 검사합니다.'),
         ('순차 실행 검증', '원본 회전·삭제와 확장 콜백을 실제 실행하여 검정 높이와 부분 트리 최대값을 비교할 수 있습니다. 사용자 공간 시험이 커널의 동시 RCU 접근까지 증명하지는 않습니다.')])

    lesson('레드블랙 양 끝·가장 왼쪽과 오른쪽 찾기', 'lib/rbtree.c', 'rb_first',
        '검색 키를 몰라도 정렬 순서의 첫 원소와 마지막 원소를 찾는 방법을 배웁니다.',
        'rb_first는 루트가 없으면 NULL이고 있으면 왼쪽 자식이 끝날 때까지 내려갑니다. rb_last는 같은 방법으로 오른쪽 끝을 찾습니다. 이진 탐색 순서에 따라 왼쪽 끝은 최소, 오른쪽 끝은 최대입니다. 기본 함수는 트리 높이만큼 이동하고 왼쪽 캐시가 있는 루트는 별도의 O(1) 접근을 제공합니다.',
        '빈 트리 반환을 확인하고 반환 rb_node에서 자료 객체를 얻습니다. 최소·최대가 필요한 기준은 삽입에 사용한 비교 순서와 같아야 합니다. 다른 필드의 최소를 자동으로 찾아주는 함수가 아닙니다.',
        '두 함수의 빈 루트 분기와 while 조건을 비교하세요.',
        [('빈 트리의 rb_first 결과는?', 'NULL이다', '가상의 최소 데이터 노드다', '루트 포인터가 없으면 즉시 NULL을 반환합니다. rb_root 구조체 자체를 자료 원소로 반환하지 않습니다.'),
         ('기본 rb_last가 이동하는 방향은?', '오른쪽 끝이다', '항상 가장 깊은 왼쪽 잎이다', '오른쪽 자식은 현재 노드보다 뒤에 오는 순서입니다. 계속 오른쪽으로 이동하면 정렬 기준의 마지막 원소가 됩니다.')],
        [('높이 비용', '균형이 유지되는 트리에서는 끝을 찾는 이동이 O(log n)입니다. 가장 왼쪽 캐시는 그 질의를 O(1)로 만들기 위해 별도 유지 비용을 지불합니다.'),
         ('객체 수명', '찾은 포인터를 반환받았다고 노드의 참조나 수명이 자동으로 보호되지 않습니다. 변경과 해제를 막는 호출자 규약이 필요합니다.')])

    lesson('레드블랙 다음·이전·부모로 올라가는 중위 순회', 'lib/rbtree.c', 'rb_next',
        '현재 노드에서 정렬 순서의 이웃을 찾는 두 가지 경로를 배웁니다.',
        'rb_next는 오른쪽 자식이 있으면 그 아래 가장 왼쪽 노드를 선택합니다. 없으면 부모로 올라가며 현재가 부모의 오른쪽 자식인 동안 계속 올라갑니다. 처음 왼쪽에서 올라온 부모가 다음 원소이고 부모가 끝나면 NULL입니다. rb_prev는 왼쪽 자식의 오른쪽 끝과 오른쪽에서 올라온 부모를 사용하는 대칭입니다.',
        'RB_EMPTY_NODE 표식이면 두 함수 모두 NULL을 반환합니다. 임의로 NULL을 node 인자로 전달하는 계약은 아니며 연결된 유효 노드 또는 명시적 빈 표식을 사용합니다. 정렬 중 부모 포인터가 일관되도록 변경 접근을 보호합니다.',
        '오른쪽 열 하강과 while의 parent 갱신을 그림으로 추적하세요.',
        [('현재에 오른쪽 자식이 있으면 다음 원소는?', '오른쪽 부분 트리의 가장 왼쪽 노드다', '무조건 오른쪽 자식 자체다', '오른쪽 부분 트리 안에도 더 작은 왼쪽 가지가 있을 수 있습니다. 그 가장 왼쪽 노드가 현재 다음의 최소입니다.'),
         ('오른쪽 자식 위치에서 부모로 올라올 때 왜 계속 올라가는가?', '그 부모는 현재보다 앞 순서이기 때문이다', '모든 부모 주소가 현재보다 작기 때문이다', '이진 탐색의 오른쪽 부분 트리는 부모보다 뒤에 있습니다. 다음 원소를 찾으려면 처음 왼쪽 가지에서 올라오는 조상이 필요합니다.')],
        [('부모 경로 주의', '소스의 lockless lookup 주석은 자식으로 내려가는 단순 탐색에 관한 제한적 설명입니다. 부모 포인터를 사용하는 중위 순회까지 같은 안전성을 확인했다고 밝히지 않습니다.'),
         ('끝 처리', '최대 노드의 rb_next와 최소 노드의 rb_prev는 NULL입니다. 순회가 끝났을 때 그 NULL을 다시 node 인자로 넘기지 않습니다.')])

    lesson('레드블랙 노드 교체·키 순서를 유지한 자리 바꾸기', 'lib/rbtree.c', 'rb_replace_node',
        '삭제와 재삽입 없이 같은 순서 위치의 노드 객체를 바꾸는 방법을 배웁니다.',
        'victim의 rb_node 전체를 new로 복사해 자식, 부모와 색을 이어받습니다. 양쪽 자식의 부모를 new로 바꾸고 기존 부모의 자식 또는 전체 루트를 new로 갱신합니다. 색과 모양이 같으므로 재균형을 수행하지 않습니다. 데이터 객체 전체를 복사하는 것이 아니라 연결 멤버를 복사합니다.',
        'new의 키가 같은 정렬 위치를 유지해야 합니다. 임의로 다른 키의 노드를 이 자리에 넣으면 탐색 순서가 깨집니다. 확장 요약값과 왼쪽 캐시는 해당 API·호출 흐름에서 별도로 유지해야 하며 victim의 해제도 수명 규약에 따릅니다.',
        '*new=*victim의 형식과 두 자식의 부모 갱신을 읽으세요.',
        [('같은 위치에 순서가 다른 키를 무조건 교체해도 되는가?', '안 되며 이웃과의 정렬 관계를 유지해야 한다', '가능하며 교체 함수가 키를 자동 재정렬한다', '교체는 연결과 색만 복사하고 검색·회전을 하지 않습니다. 잘못된 키는 이진 탐색의 위치 조건을 깨뜨립니다.'),
         ('*new=*victim이 복사하는 것은?', 'rb_node 연결과 부모·색 정보다', '자료 객체의 모든 사용자 필드다', '두 인자의 형식은 rb_node 포인터입니다. 포함 객체의 키나 요약값 같은 다른 필드는 이 대입의 범위가 아닙니다.')],
        [('빈 표식', 'victim의 연결 정보는 원본에 남습니다. 더 이상 삽입되지 않은 표식이 필요하면 호출자가 RB_CLEAR_NODE를 처리합니다.'),
         ('확장 자료', '요약 필드는 rb_node 밖에 있으므로 단순 교체만으로 자동 복사되지 않습니다. 새 객체의 요약과 검색 기준을 정확히 준비해야 합니다.')])

    lesson('레드블랙 RCU 교체·초기화 뒤 마지막 공개', 'lib/rbtree.c', 'rb_replace_node_rcu',
        '독자가 새 객체로 내려가기 전에 후속 연결을 준비해 공개하는 순서의 의미를 배웁니다.',
        '기본 교체처럼 새 노드 연결과 자식 부모를 먼저 준비합니다. 마지막 상위 자식 포인터 갱신은 __rb_change_child_rcu의 rcu_assign_pointer를 사용합니다. 독자가 새 노드를 관찰할 때 그 뒤의 연결도 준비되어 있도록 공개 순서를 만듭니다. 이전 객체를 즉시 해제하거나 모든 회전을 원자적으로 보이게 하는 동작은 아닙니다.',
        'writer 직렬화, 독자 보호 구간과 이전 노드의 지연 해제를 함께 설계해야 합니다. 소스 주석은 동시 회전에서 탐색이 부분 트리를 놓칠 수 있다고 설명하므로 반환 없음이 존재하지 않음의 증거가 되지 않습니다.',
        '기본 교체와 마지막 __rb_change_child_rcu 호출의 차이를 읽으세요.',
        [('새 노드를 상위 포인터에 먼저 공개하고 나중에 자식을 초기화해도 되는가?', '안 되며 후속 연결을 먼저 준비해야 한다', 'RCU라는 이름이면 순서와 상관없다', '독자는 공개된 새 노드에서 후속 연결을 읽을 수 있습니다. 원본은 초기화 후 마지막 release 공개를 사용합니다.'),
         ('동시 회전 중 lockless 탐색이 NULL을 반환했다면?', '실제로 존재하는 노드를 놓쳤을 수도 있다', '반드시 그 키가 트리에 없다는 뜻이다', '원본은 회전이 원자적이지 않아 부분 트리를 놓치는 false negative를 허용한다고 명시합니다. 제한적인 관찰 계약을 이해해야 합니다.')],
        [('WRITE_ONCE 범위', '소스는 자식 필드 쓰기와 일시적 순환 방지를 통해 단순 하강이 루프에 빠지지 않도록 설명합니다. 그것만으로 완전한 순회·스냅샷·수명 보호를 제공한다고 확대하지 않습니다.'),
         ('시험 문맥', '사용자 공간 시험의 RCU 공개 대체는 순차 연결 동작을 검사합니다. 실제 커널 release·독자·grace period와 동시 메모리 모델의 검증으로 표시하지 않습니다.')])

    lesson('레드블랙 후위 순회·자식부터 방문하는 깊은 노드', 'lib/rbtree.c', 'rb_next_postorder',
        '자식을 먼저 처리하고 부모를 나중에 처리하는 순회 순서와 다음 노드 계산을 배웁니다.',
        'rb_left_deepest_node는 왼쪽 자식이 있으면 내려가고 없으면 오른쪽 자식으로 내려가며 잎을 찾습니다. rb_first_postorder는 루트 아래 그 잎에서 시작합니다. rb_next_postorder는 왼쪽 자식에서 올라왔고 오른쪽 형제가 있으면 그 형제의 가장 깊은 노드로 이동합니다. 아니면 부모를 다음으로 선택합니다. NULL 입력은 NULL을 반환합니다.',
        '트리 전체 객체를 자식부터 정리할 때 사용할 수 있습니다. 순회 도중 rb_erase로 회전시키면 다음 순서가 바뀌므로 safe 매크로의 보장을 넘어섭니다. 현재 객체 해제 허용과 트리 재균형 허용을 구분합니다.',
        '왼쪽 우선 깊은 하강과 node==parent->rb_left 조건을 읽으세요.',
        [('왼쪽 자식 방문 후 오른쪽 형제가 남아 있으면 다음은?', '오른쪽 형제 아래의 후위 시작 노드다', '오른쪽 가지를 생략하고 무조건 부모다', '부모보다 모든 자식을 먼저 방문해야 합니다. 오른쪽 부분 트리가 남았다면 그 아래부터 끝내고 부모로 올라갑니다.'),
         ('safe 후위 순회에서 현재 노드에 rb_erase를 호출해도 되는가?', '재균형으로 순서가 바뀔 수 있어 보장되지 않는다', 'safe라는 이름이면 모든 수정이 허용된다', '매크로는 현재의 다음 위치를 미리 저장합니다. 원본 주석은 rb_erase의 회전 등 순서 재배치를 처리하지 못해 일부 노드를 놓칠 수 있다고 설명합니다.')],
        [('순서와 키', '후위 순회는 키 오름차순이 아닙니다. 목적은 부모를 자식 뒤에 방문하는 것이며 중위 rb_next 순회와 다릅니다.'),
         ('빈 루트와 끝', '빈 루트의 first_postorder와 루트 방문 뒤 next_postorder는 NULL입니다. next_postorder는 명시적으로 NULL 입력도 검사하는 점이 rb_next와 다릅니다.')])
